<script>
 import {strategyReturnContext} from '../../lib/defiant-location.js';
 import {untrack,onDestroy,tick} from 'svelte';
 import DefiantDiscovery from './DefiantDiscovery.svelte';
 import DefiantClip from './DefiantClip.svelte';
 import DefiantPreprocess from './DefiantPreprocess.svelte';
 let {state:workspace,location,request,onSaved,onNavigate,onDirtyChange=()=>{}}=$props();
 let briefSection=$state(null),briefTitle=$state(null);
 let projected=$state(null),projectionSequence=0;
 const box=$derived(projected||workspace.inbox||{sources:[],matches:[],recordings:[],workstreams:[]});
 const source=$derived(box.selected?.id===location.sourceId?box.selected:box.sources.find(s=>s.id===location.sourceId));
 const catalog=$derived(box.catalogGroups?.[0]);
 const catalogRecordings=$derived(catalog?box.recordings.filter(r=>catalog.recordingIds.includes(r.id)):box.recordings);
 const match=$derived(box.matches.find(m=>m.sourceId===source?.id));
 let loaded=$state(''),loadedRevision=$state(0),recordingId=$state(''),workstreamId=$state(''),stage=$state('new'),rationale=$state(''),base=$state(''),note=$state('');
 let busy=$state(false),error=$state(''),notice=$state(''),preview=$state(null),intent=$state(null),unknown=$state(false),reportTitle=$state('');
 let momentDirty=$state(false),selectedMoment=$state(null),selectedAnalysisId=$state(''),clipMoment=$state(null);
 let matchDetailsOpen=$state(false);
 $effect(()=>{source?.id;untrack(()=>{matchDetailsOpen=!match;});});
 let clipDirty=$state(false),discoveryDirty=$state(false),packKind=$state('nipsey-example');
 let alive=true;onDestroy(()=>{alive=false;onDirtyChange(false);});
 async function refreshProjection(){const ticket=++projectionSequence;try{const result=await request('/inbox'+(location.sourceId?'?sourceId='+encodeURIComponent(location.sourceId):''));if(alive&&ticket===projectionSequence)projected=result;}catch(e){if(alive&&ticket===projectionSequence)error=e.message;}}
 $effect(()=>{workspace.revision;location.sourceId;untrack(()=>void refreshProjection());});
 const proposalDirty=$derived(JSON.stringify([recordingId,workstreamId,stage,rationale])!==base&&Boolean(loaded));
 const dirty=$derived(clipDirty||momentDirty||discoveryDirty||proposalDirty||Boolean(note.trim()||reportTitle.trim()||intent||preview));
 $effect(()=>onDirtyChange(dirty));
 function adopt(){loaded=source?.id||'';loadedRevision=match?.revision||0;recordingId=match?.recordingId||'';workstreamId=match?.workstreamId||'';stage=match?.stage||'new';rationale=match?.rationale||'';base=JSON.stringify([recordingId,workstreamId,stage,rationale]);}
 $effect(()=>{source?.id;match?.revision;untrack(()=>{if(!proposalDirty&&!intent)adopt();});});
 function navigate(next){if(dirty){error='Save or clear your working text before changing the inbox selection.';return;}onNavigate({...location,...next,...(next.sourceId&&next.sourceId!==location.sourceId?{clipId:'',momentId:''}:{}),view:'inbox'});}
 const rows=$derived.by(()=>{const q=(location.query||'').toLowerCase().trim();return box.sources.filter(s=>{const m=box.matches.find(x=>x.sourceId===s.id),r=box.recordings.find(x=>x.id===m?.recordingId);return (!location.cohort||location.cohort==='all'||s.cohorts?.includes(location.cohort))&&(!location.workstreamId||m?.workstreamId===location.workstreamId)&&(!location.inboxStage||m?.stage===location.inboxStage)&&(!location.recordingId||m?.recordingId===location.recordingId)&&(!q||[s.title,s.creator,s.creatorHandle,r?.title].some(x=>x?.toLowerCase().includes(q)));}).sort((a,b)=>(latestObservation(b,'views')?.value??-1)-(latestObservation(a,'views')?.value??-1));});
 const notes=$derived(workspace.annotations.filter(a=>a.target?.kind==='source'&&a.target.id===source?.id));
 function latestObservation(s,metric){const time=o=>Date.parse(o.observedAt)||Number(o.observedAt)||0;return [...(s.observations||[])].filter(o=>o.metric===metric).sort((a,b)=>time(b)-time(a))[0];}
 function count(s,metric){const n=latestObservation(s,metric)?.value;return typeof n==='number'?n.toLocaleString():'Unknown';}
 async function inspect(){if(busy||unknown)return;busy=true;error='';try{const value=await request('/inbox/import/preview',{method:'POST',body:JSON.stringify({kind:packKind})});if(alive)preview=value;}catch(e){if(alive)error=e.message;}finally{if(alive)busy=false;}}
 async function send(path,payload,kind){if(busy||unknown)return;intent={path,kind,body:{expectedRevision:workspace.revision,idempotencyKey:crypto.randomUUID(),...payload}};await submit();}
 async function submit(){if(busy||!intent)return;busy=true;error='';notice='';try{const ack=await request(intent.path,{method:'POST',body:JSON.stringify(intent.body)});if(!alive)return;const kind=intent.kind;intent=null;unknown=false;if(kind==='import')preview=null;if(kind==='note')note='';if(kind==='match'){loadedRevision=ack.match.revision;base=JSON.stringify([recordingId,workstreamId,stage,rationale]);}if(kind==='report')reportTitle='';notice=kind==='import'?'Example research pack saved':kind==='match'?'Proposed match saved':kind==='note'?'Shared note saved':'Report saved';try{await onSaved(ack);if(kind==='report')onNavigate({...location,view:'report',reportId:ack.report.id});}catch{error='Your save succeeded. Reload to see the saved references.';}}catch(e){if(!alive)return;error=e.status===409?'Saved work changed. Your text is retained. Reload current references and compare before saving again.':e.message;unknown=!(Number.isInteger(e.status)&&e.status>=400&&e.status<500);if(!unknown)intent=null;}finally{if(alive)busy=false;}}
 function saveMatch(){void send('/inbox/sources/'+encodeURIComponent(source.id)+'/match',{expectedMatchRevision:loadedRevision,match:{recordingId,workstreamId,stage,rationale}},'match');}
 function saveNote(){void send('/annotations',{annotation:{target:{kind:'source',id:source.id},kind:'note',text:note,labels:[],evidenceIds:[]}},'note');}
 function report(){if(!source||!match)return;void send('/reports',{report:{title:reportTitle.trim()||(source.provenance?.commit?source.title:'Creator source planning brief'),thesis:'',returnContext:strategyReturnContext({...location,origin:'catalog'}),planIds:[],sourceRefs:[source.id],matchRefs:[{sourceId:source.id,id:match.id,revision:match.revision}],...(location.clipId?{clipRefs:[{artifactId:location.clipId}]}:{}),...(selectedMoment?{momentRefs:[{analysisId:selectedAnalysisId,momentId:selectedMoment.id,revision:selectedMoment.revision}]}:{})}},'report');}
 async function focusBrief(){await tick();briefSection?.scrollIntoView({behavior:'smooth',block:'start'});briefTitle?.focus({preventScroll:true});}
 async function reload(){try{await onSaved();}catch(e){error=e.message;}}
 function clear(){if(unknown||busy)return;note='';reportTitle='';preview=null;intent=null;error='';adopt();}
</script>
<section class="video-inbox" aria-label="Creator videos inbox">
 <header><div><span class="eyebrow">CATALOG-LED</span><h2>{catalog?.artist||'Artist catalog'}</h2><p>Choose a recording, inspect a source, then save a moment for your campaign.</p>{#if catalog}<small>{catalog.sourceIds.length} retained supplied sources · {catalog.recordingIds.length} retained recordings <span>Reference pack: {catalog.referenceCounts.sources} sources / {catalog.referenceCounts.recordings} recordings · unverified</span></small>{/if}</div><details class="pack-tools"><summary>Reference packs</summary><label>Reference pack<select bind:value={packKind} disabled={busy||unknown||dirty}><option value="nipsey-example">Nipsey example · 45 supplied sources</option><option value="nipsey-historical20">Historical sample · 20 supplied sources</option></select></label><button class="secondary" disabled={busy||unknown||dirty} onclick={inspect}>{packKind==='nipsey-example'?'Preview Nipsey example pack':'Preview historical sample pack'}</button></details></header>
 {#if catalogRecordings.length}<div class="catalog-recordings" aria-label="Artist catalog recordings"><button class:chosen={!location.recordingId} disabled={dirty||busy} onclick={()=>navigate({origin:'catalog',recordingId:'',sourceId:'',momentId:'',clipId:''})}>All recordings</button>{#each catalogRecordings as recording(recording.id)}<button class:chosen={location.recordingId===recording.id} disabled={dirty||busy} onclick={()=>navigate({origin:'catalog',recordingId:recording.id,sourceId:'',momentId:'',clipId:''})}>{recording.title}</button>{/each}</div>{/if}
 {#if error}<p role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if unknown}<p>The reply was interrupted. Keep this request to check its outcome.</p><button disabled={busy} onclick={submit}>Retry same save</button>{:else if error}<button disabled={busy} onclick={reload}>Reload current references</button>{/if}
 {#if preview}<section class="import" aria-label="Source import preview"><h3>{preview.kind==='nipsey-historical20'?'Historical sample · 20 supplied sources':'Nipsey catalog discovery example'}</h3><p>{Object.entries(preview.counts).map(([kind,c])=>`${kind}: ${c.new} new, ${c.unchanged} unchanged, ${c.conflicting} conflicting`).join(' · ')}</p>{#each preview.warnings as warning(warning)}<p>{warning}</p>{/each}<button disabled={busy||unknown||Object.values(preview.counts).some(c=>c.conflicting)} onclick={()=>send('/inbox/import',{kind:preview.kind,previewDigest:preview.previewDigest,expectedRevision:preview.expectedRevision},'import')}>Add these sources</button><button disabled={busy||unknown} onclick={()=>preview=null}>Cancel import</button></section>{/if}
 <DefiantDiscovery {request} revision={workspace.revision} onSaved={onSaved} onDirtyChange={value=>discoveryDirty=value}/>
 {#if !box.sources.length}<div class="empty"><h3>Your source inbox is empty</h3><p>Preview the supplied Nipsey research pack to begin. No videos are downloaded and no sources are marked cleared.</p></div>
 {:else}
 <p class="context">Recording matches are proposals. Source counts keep their observation dates.</p>
 <form class="filters" onsubmit={e=>e.preventDefault()}><label>Search title, creator or song<input type="search" value={location.query||''} disabled={dirty||busy} onchange={e=>navigate({query:e.currentTarget.value})}/></label><details><summary>Filter sources</summary><div class="secondary-filters"><label>Cohort<select value={location.cohort||'all'} disabled={dirty||busy} onchange={e=>navigate({cohort:e.currentTarget.value})}><option value="all">All sources</option><option value="supplied-2026">2026 supplied pack</option><option value="historical-sample">Historical samples</option><option value="youtube-discovery">YouTube discovery</option></select></label><label>Workstream<select value={location.workstreamId||''} disabled={dirty||busy} onchange={e=>navigate({workstreamId:e.currentTarget.value})}><option value="">All workstreams</option>{#each box.workstreams as w(w.id)}<option value={w.id}>{w.name}</option>{/each}</select></label><label>Stage<select value={location.inboxStage||''} disabled={dirty||busy} onchange={e=>navigate({inboxStage:e.currentTarget.value})}><option value="">All stages</option>{#each ['new','considering','selected','parked'] as value(value)}<option {value}>{value}</option>{/each}</select></label><label>Recording<select value={location.recordingId||''} disabled={dirty||busy} onchange={e=>navigate({recordingId:e.currentTarget.value})}><option value="">All recordings</option>{#each box.recordings as r(r.id)}<option value={r.id}>{r.title}</option>{/each}</select></label><button disabled={dirty||busy} onclick={()=>navigate({query:'',cohort:'',workstreamId:'',inboxStage:'',recordingId:''})}>Reset filters</button></div></details></form>
 <p role="status">{rows.length} of {box.sources.length} sources · ordered by latest reported views</p>
 <div class="inbox-layout" class:has-selection={Boolean(source)}><div class="table-scroll"><table><caption>Creator video sources</caption><thead><tr><th scope="col">Source / creator</th><th scope="col">Proposed recording</th><th scope="col">Views</th><th scope="col">Stage</th></tr></thead><tbody>{#each rows as s(s.id)}{@const m=box.matches.find(m=>m.sourceId===s.id)}<tr class={{chosen:source?.id===s.id}}><th scope="row"><button disabled={busy||dirty} aria-pressed={source?.id===s.id} onclick={()=>navigate({sourceId:s.id})}>{s.title}</button><small>{s.creator}</small></th><td>{box.recordings.find(r=>r.id===m?.recordingId)?.title||'Unmatched'}</td><td>{count(s,'views')}</td><td>{m?.stage||'new'}</td></tr>{:else}<tr><td colspan="4">No matching sources. Reset the filters to see your inbox.</td></tr>{/each}</tbody></table></div>
 <aside aria-label="Source inspector">{#if source}<h3>{source.title}</h3><p>{source.creator} · {source.publishedAt||'Date unknown'}</p>{#if match}<p class="selected-recording">Proposed recording: <strong>{box.recordings.find(r=>r.id===match.recordingId)?.title||'Unmatched'}</strong></p>{/if}<button class="brief-action" onclick={focusBrief}>Prepare campaign brief</button><a href={source.sourceUrl} target="_blank" rel="noopener noreferrer">Open source on YouTube ↗</a><p>Analyze the source link first, or open it on YouTube. Supply permitted files only when you are ready to render.</p><details class="source-evidence"><summary>Source evidence and provenance</summary><dl><dt>Likes</dt><dd>{count(source,'likes')} · {latestObservation(source,'likes')?.method==='youtube-data-api'?'YouTube API':latestObservation(source,'likes')?'Supplied, observation date unknown':'Not reported'}</dd><dt>Comments</dt><dd>{count(source,'comments')} · {latestObservation(source,'comments')?.method==='youtube-data-api'?'YouTube API':latestObservation(source,'comments')?'Supplied, observation date unknown':'Not reported'}</dd><dt>Supplied hook, not a verified claim</dt><dd>{source.narrativeHook}</dd><dt>Reference</dt><dd>{#if source.provenance?.commit}defiant-os · {source.provenance.commit.slice(0,7)} · row {source.original?.rank||'unknown'}{:else if source.provenance?.kind==='supplied-historical-sample'}Supplied historical sample · unverified{:else}YouTube discovery{/if}</dd>{#if source.liveMetadata}<dt>YouTube API checked</dt><dd>{source.liveMetadata.observedAt}</dd>{/if}</dl>
 {#if source.observationHistory?.length}<details><summary>YouTube observation history ({source.observationHistory.length})</summary><p>API observations expire after 30 days. Missing counts remain unknown; these observations do not establish a trend.</p><table class="observation-history" aria-label="YouTube observation history"><thead><tr><th>Checked</th><th>Views</th><th>Likes</th><th>Comments</th></tr></thead><tbody>{#each source.observationHistory as observation(observation.runId)}<tr><td>{observation.observedAt}</td>{#each ['views','likes','comments'] as metric(metric)}<td>{typeof observation.statistics[metric]==='number'?observation.statistics[metric].toLocaleString():'Unknown'}</td>{/each}</tr>{/each}</tbody></table></details>{/if}
 {#if source.observations.some(o=>o.method==='supplied-example')}<details><summary>Imported counts · observation date unknown</summary><dl>{#each source.observations.filter(o=>o.method==='supplied-example') as observation(observation.metric)}<dt>{observation.metric}</dt><dd>{observation.value.toLocaleString()} · Supplied example, not independently verified</dd>{/each}</dl></details>{/if}
 {#each source.suppliedReferences||[] as reference(reference.packId)}<details><summary>Historical sample reference · supplied and unverified</summary><p>Provided {reference.provenance.providedOn}; observation date unknown. This reference does not replace your current match or note.</p><dl><dt>Original row</dt><dd>{reference.source.original?.rank||'Unknown'}</dd><dt>Supplied title</dt><dd>{reference.source.title}</dd><dt>Proposed recording / ISRC</dt><dd>{reference.source.original?.track||'Unknown'} · {reference.source.original?.matchedIsrc||'Unknown'} · unverified</dd>{#each reference.source.observations as observation(observation.metric)}<dt>Supplied {observation.metric}</dt><dd>{observation.value.toLocaleString()} · observation date unknown</dd>{/each}</dl></details>{/each}</details>
 {#key source.id}<DefiantPreprocess {source} recordings={box.recordings} {request} selectedMomentId={location.momentId||''} onMomentChange={momentId=>onNavigate({...location,view:'inbox',momentId})} onSelection={(moment,analysisId)=>{selectedMoment=moment;selectedAnalysisId=analysisId;}} onUseMoment={moment=>{clipMoment={...moment,sourceId:source.id,recordingTitle:box.recordings.find(r=>r.id===moment.recordingId)?.title||'',selectionKey:crypto.randomUUID()};}} onDirtyChange={value=>momentDirty=value} onSaved={onSaved}/>{/key}
 <details class="match-details" bind:open={matchDetailsOpen}><summary>Recording match and rationale</summary><fieldset disabled={busy||unknown}><legend>Proposed catalog match</legend><label>Recording<select bind:value={recordingId}><option value="">Choose a recording</option>{#each box.recordings as r(r.id)}<option value={r.id}>{r.title}</option>{/each}</select></label><p>Supplied ISRC: {box.recordings.find(r=>r.id===recordingId)?.suppliedIsrc||'Unknown'}. Unverified; choosing a track does not grant audio permission.</p><label>Workstream<select bind:value={workstreamId}><option value="">Choose a workstream</option>{#each box.workstreams as w(w.id)}<option value={w.id}>{w.name}</option>{/each}</select></label><label>Planning stage<select bind:value={stage}>{#each ['new','considering','selected','parked'] as value(value)}<option {value}>{value}</option>{/each}</select></label><label>Why this song fits<textarea bind:value={rationale} rows="3" maxlength="2000"></textarea></label>{#if match&&match.revision!==loadedRevision}<p>A newer match is saved. Your wording is retained.</p><button onclick={()=>{loadedRevision=match.revision;}}>Keep my wording on the current version</button>{/if}<button disabled={!proposalDirty||!recordingId||!workstreamId||!rationale.trim()} onclick={saveMatch}>Save proposed match</button></fieldset></details>
 {#if match?.originalImported}<details><summary>Original supplied proposal</summary><p>{match.originalImported.rationale}</p><p>{box.recordings.find(r=>r.id===match.originalImported.recordingId)?.title}{#if source.original?.stage} · supplied stage: {source.original.stage}{/if}. Supplied proposals do not establish clearance.</p></details>{/if}
 <section aria-label="Shared source notes"><h4>Manager notes</h4>{#each notes as n(n.id)}<blockquote>{n.text}<small>Saved note · revision {n.revision}</small></blockquote>{:else}<p>No shared notes yet.</p>{/each}<label>Your note<textarea bind:value={note} disabled={busy||unknown} maxlength="6000" rows="3"></textarea></label><button disabled={busy||unknown||!note.trim()} onclick={saveNote}>Save source note</button></section>
 {#key source.id}<DefiantClip {source} proposedMoment={clipMoment?.sourceId&&clipMoment.sourceId!==source.id?null:clipMoment} recordingId={match?.recordingId||''} {request} selectedClipId={location.clipId||''} onClipChange={clipId=>onNavigate({...location,view:'inbox',clipId})} onDirtyChange={value=>clipDirty=value}/>{/key}
 <section class="report" bind:this={briefSection}><h4>Next: prepare the campaign brief</h4><p>Add this source, saved match{location.clipId?' and selected MP4':''} to a report. Choose a destination there.</p><label>Report title<input bind:this={briefTitle} bind:value={reportTitle} disabled={busy||unknown} maxlength="300" placeholder={source.title}/></label><button disabled={busy||unknown||!match||proposalDirty||clipDirty||momentDirty||discoveryDirty||Boolean(note.trim())} onclick={report}>Add source to report</button><button disabled={busy||dirty} onclick={()=>onNavigate({...location,view:'map',origin:'talent',focus:'',selected:''})}>Explore graph context</button></section>
 {:else}<h3>Inspect a source</h3><p>Choose a video to see its supplied context and propose a recording match.</p>{/if}</aside></div>
 {/if}
 {#if (proposalDirty||note.trim()||reportTitle.trim()||preview)&&!unknown}<button disabled={busy} onclick={clear}>Clear match, note and report text</button>{/if}
</section>
<style>
.catalog-recordings{display:flex;gap:7px;overflow-x:auto;padding:10px 0 12px;border-bottom:1px solid #dedfd8}.catalog-recordings button{white-space:nowrap;flex:0 0 auto;padding:7px 11px;border-radius:20px}.catalog-recordings .chosen{background:#315d45;color:white}.eyebrow{font-size:10px;letter-spacing:.12em;color:#69765f;font-weight:650}.pack-tools{min-width:160px;font-size:12px}.pack-tools[open]{max-width:300px}.secondary-filters{display:flex;gap:12px;flex-wrap:wrap}.filters>details{align-self:center;min-width:120px}.source-evidence,.match-details{font-size:13px}.video-inbox header small span{display:block;margin-top:3px}.observation-history td:first-child{overflow-wrap:anywhere}.video-inbox{padding:16px 20px;min-width:0}.video-inbox header{display:flex;justify-content:space-between;align-items:start;gap:20px}.video-inbox h2{margin:0;font-size:24px}.video-inbox p{line-height:1.5;margin:6px 0 10px}.context{color:#596a51;font-size:13px}.filters{display:flex;flex-wrap:wrap;align-items:end;gap:12px}.filters label:first-child{flex:1;min-width:220px}.video-inbox label{display:block;font-size:13px;margin:10px 0}.video-inbox input,.video-inbox select,.video-inbox textarea{display:block;width:100%;font:inherit;margin-top:5px}.inbox-layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,1fr);gap:18px}.table-scroll{max-height:75vh;overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}caption{text-align:left;font-weight:650;padding:12px 0}th,td{text-align:left;padding:12px;border-bottom:1px solid #dedfd8;vertical-align:top}th button{background:transparent;color:inherit;text-align:left;border:0;padding:0;white-space:normal;line-height:1.5}small{display:block;color:#69765f;margin-top:4px}.chosen{background:#edf2e8}aside{position:sticky;top:12px;max-height:calc(100vh - 100px);overflow:auto;border-left:1px solid #dedfd8;padding-left:20px}aside h3{font-size:20px;line-height:1.4;margin-top:0}fieldset{border:1px solid #dedfd8;padding:12px}legend{font-weight:650}dd{margin:4px 0 12px;line-height:1.5}dt{font-size:12px;color:#69765f}details,.report{margin:18px 0}summary{cursor:pointer}button{margin:4px 8px 4px 0}blockquote{margin:12px 0;padding-left:12px;border-left:2px solid #bdcbb4}.import,.empty{border:1px solid #dedfd8;padding:18px;margin-top:16px}@media(max-width:1000px){.inbox-layout{grid-template-columns:1fr}.inbox-layout.has-selection aside{grid-row:1}.inbox-layout.has-selection .table-scroll{grid-row:2}.table-scroll{max-height:45vh}aside{position:sticky;top:12px;max-height:calc(100vh - 100px);overflow:auto;border-left:0;border-top:1px solid #dedfd8;padding:20px 0}.video-inbox header{flex-wrap:wrap}}
</style>
